const items = $input.all();
const posts = items[0].json.data || [];

// Quality filters
const MIN_LIKES = 10;
const MIN_CAPTION_LENGTH = 20;

const quality = posts.filter(post => {
  const likes = post.like_count || 0;
  const captionLen = (post.caption || '').length;
  const isImage = post.media_type === 'IMAGE' || post.media_type === 'CAROUSEL_ALBUM';
  return likes >= MIN_LIKES && captionLen >= MIN_CAPTION_LENGTH && isImage;
});

return quality.map(post => ({
  json: {
    post_id: post.id,
    caption: post.caption,
    media_url: post.media_url,
    permalink: post.permalink,
    like_count: post.like_count,
    comments_count: post.comments_count,
    media_type: post.media_type,
    timestamp: post.timestamp,
    collected_at: new Date().toISOString(),
    status: 'pending_approval'
  }
}));

